begin;
create function pg_temp.assert_ok(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'TEST FAILED: %',label;end if;end$$;
create function pg_temp.denied(statement text,expected text,label text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=expected then return;end if;raise exception 'TEST FAILED %: got % (%)',label,sqlstate,sqlerrm;end;raise exception 'TEST FAILED %: accepted',label;end$$;
insert into auth.users(id,email,email_confirmed_at,encrypted_password) values
 ('10000000-0000-4000-8000-000000000001','boundary-owner@example.invalid',now(),'test'),
 ('20000000-0000-4000-8000-000000000002','boundary-admin@example.invalid',now(),'test'),
 ('30000000-0000-4000-8000-000000000003','boundary-target@example.invalid',now(),'test'),
 ('40000000-0000-4000-8000-000000000004','boundary-other@example.invalid',now(),'test');
update realm_private.accounts set state='active';
update realm_private.settings set value='true' where key in ('administration','privacy_jobs');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select set_config('realm.boundary.space',public.manage_space('create',p_name=>'Boundary space')::text,true);
select set_config('realm.boundary.channel',(select id::text from public.channels where space_id=current_setting('realm.boundary.space')::uuid),true);
select set_config('realm.boundary.admin',public.membership_invite('create',current_setting('realm.boundary.space')::uuid,'boundary-admin@example.invalid')->>'token',true);
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select public.membership_invite('redeem',p_token=>current_setting('realm.boundary.admin'));
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select public.manage_space('role',current_setting('realm.boundary.space')::uuid,'20000000-0000-4000-8000-000000000002',p_role=>'admin',p_revision=>0);
select public.set_block('30000000-0000-4000-8000-000000000003',true);
select pg_temp.denied(format('select public.membership_invite(''create'',%L,''boundary-target@example.invalid'')',current_setting('realm.boundary.space')),'42501','issuer/recipient block prevents that invitation');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select set_config('realm.boundary.token',public.membership_invite('create',current_setting('realm.boundary.space')::uuid,'boundary-target@example.invalid')->>'token',true);
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000003',true);
select public.membership_invite('redeem',p_token=>current_setting('realm.boundary.token'));
select pg_temp.assert_ok((select count(*)=1 from public.spaces),'another member block is not a space ban');
-- Owner transfer is atomic and leaves exactly one owner.
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select pg_temp.denied(format('select public.manage_space(''leave'',%L)',current_setting('realm.boundary.space')),'42501','last owner cannot leave');
select public.manage_space('transfer',current_setting('realm.boundary.space')::uuid,'20000000-0000-4000-8000-000000000002',p_revision=>1);
select set_config('realm.boundary.issued',public.membership_invite('create',current_setting('realm.boundary.space')::uuid,'boundary-other@example.invalid')->>'token',true);
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select public.manage_space('role',current_setting('realm.boundary.space')::uuid,'10000000-0000-4000-8000-000000000001',p_role=>'member',p_revision=>2);
select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000004',true);
select pg_temp.denied(format('select public.membership_invite(''redeem'',p_token=>%L)',current_setting('realm.boundary.issued')),'42501','issuer demotion invalidates pending grants');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select public.manage_space('role',current_setting('realm.boundary.space')::uuid,'10000000-0000-4000-8000-000000000001',p_role=>'admin',p_revision=>3);
select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000004',true);
select pg_temp.denied(format('select public.membership_invite(''redeem'',p_token=>%L)',current_setting('realm.boundary.issued')),'42501','restoring authority does not revive revoked grants');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select public.manage_channel('archive',current_setting('realm.boundary.space')::uuid,current_setting('realm.boundary.channel')::uuid,p_revision=>0);
select pg_temp.denied(format('select public.message_send(''channel'',%L,''archived'',gen_random_uuid())',current_setting('realm.boundary.channel')),'42501','archived channel refuses sends');
select public.manage_channel('restore',current_setting('realm.boundary.space')::uuid,current_setting('realm.boundary.channel')::uuid,p_revision=>1);
select set_config('realm.boundary.message',public.message_send('channel',current_setting('realm.boundary.channel')::uuid,'Can be reported',gen_random_uuid())::text,true);
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000003',true);
select public.message_read('channel',current_setting('realm.boundary.channel')::uuid,current_setting('realm.boundary.message')::uuid);
select pg_temp.assert_ok(public.message_unread('channel',current_setting('realm.boundary.channel')::uuid)=0,'read position counts only reached messages');
select set_config('realm.boundary.membermessage',public.message_send('channel',current_setting('realm.boundary.channel')::uuid,'Member abuse',gen_random_uuid())::text,true);
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select set_config('realm.boundary.report',public.submit_report('channel',current_setting('realm.boundary.channel')::uuid,current_setting('realm.boundary.membermessage')::uuid,p_reason=>'spam')::text,true);
select public.review_report(current_setting('realm.boundary.report')::uuid,0,'ban','Repeated abuse',24);
select pg_temp.denied(format('select public.membership_invite(''create'',%L,''boundary-target@example.invalid'')',current_setting('realm.boundary.space')),'42501','explicit ban excludes every issuer');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_ok((select count(*)=0 from public.messages),'ban removes read access on old session');
select pg_temp.denied(format('select public.message_history(''channel'',%L)',current_setting('realm.boundary.channel')),'42501','ban prevents history RPC');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims',jsonb_build_object('amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch from clock_timestamp()))))::text,true);
select set_config('realm.boundary.delete',public.privacy_request('delete',p_close_spaces=>true)->>'id',true);
reset role;
select pg_temp.assert_ok((select count(*)=1 from public.space_members where space_id=current_setting('realm.boundary.space')::uuid and role='owner'),'exactly one owner after transfer');
select pg_temp.assert_ok((select count(*)>0 from realm_private.audit where action='settings.changed'),'operator configuration audited');
select pg_temp.assert_ok((select bool_and(a.expires_at<=r.expires_at) from realm_private.audit a join realm_private.reports r on r.id=a.target where r.id=current_setting('realm.boundary.report')::uuid),'case audit deadlines follow closure');
update realm_private.privacy_jobs set not_before=clock_timestamp()-interval '1 second' where id=current_setting('realm.boundary.delete')::uuid;
select realm_private.process_privacy_jobs();
select pg_temp.assert_ok((select closed_at is not null and archived_at is not null from public.spaces where id=current_setting('realm.boundary.space')::uuid),'explicit closure preserves read-only space');
select set_config('request.jwt.claim.sub','',true);
delete from auth.users where id='20000000-0000-4000-8000-000000000002';
select pg_temp.assert_ok((select body='Member abuse' from public.messages where id=current_setting('realm.boundary.membermessage')::uuid),'space closure preserves peer contributions');
set constraints all immediate;
rollback;
